using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class PersonalStartTests
{
    static WorldSession New()=>new(PersonalStart.Create());
    static void Accept(WorldSession s){var c=RegionalWork.Inbox(s).Single();Assert.Equal(ResultCode.Accepted,s.Open(PersonalStart.Person,c.Message,s.Revision).Code);c=RegionalWork.Inbox(s).Single();Assert.Equal(ResultCode.Accepted,s.Assent(c.Task!.Value,PersonalStart.Person,true,s.Revision).Code);s.SetPaused(false);}
    static void Continue(WorldSession s){s.SetPaused(false);if(s.Seconds<2)s.AdvanceTo(2);if(RegionalWork.Inbox(s).Any(c=>c.CanOpen))Accept(s);s.SetPaused(false);s.AdvanceTo(9);}
    [Fact] public void IndependentRoninStartsWithoutInheritedRightsOrMemory(){var w=PersonalStart.Create();Assert.Equal(PersonalStart.Person,w.PlayerControl);Assert.DoesNotContain(w.Knowledge,k=>k.Character==w.PlayerControl);Assert.DoesNotContain(w.Memberships,m=>m.Subject==w.PlayerControl);Assert.DoesNotContain(w.ServiceBonds,b=>b.Subject==w.PlayerControl||b.Target==w.PlayerControl);Assert.DoesNotContain(w.Units,u=>u.Commander==w.PlayerControl);Assert.Equal(4,w.Grants.Count(g=>g.Agent==w.PlayerControl));Assert.True(StartConfiguration.Check(w,StartConfiguration.Describe(w,w.PlayerControl,StartTemplate.Ronin,PersonOrigin.Created,PersonalStart.Policy),PersonalStart.Policy).Eligible);}
    [Fact] public void SameDefinitionAndSeedAreDeterministicAndDifferentSeedIsBound(){Assert.Equal(ContractJson.Write(PersonalStart.Create()),ContractJson.Write(PersonalStart.Create()));var a=PersonalStart.Create("浪人A",1);var b=PersonalStart.Create("浪人A",2);Assert.NotEqual(a.Definitions.Version,b.Definitions.Version);Assert.NotEqual(a.RandomStreams[0].State,b.RandomStreams[0].State);Assert.NotEqual(a.Definitions.Version,PersonalStart.Create("浪人B",1).Definitions.Version);}
    [Fact] public void LegacyProfileBytesAndHistoricalSeedsArePreserved(){var before=ContractJson.Write(NpcWork.Create());var old=NpcWork.Create();var fresh=PersonalStart.Create();Assert.Equal(before,ContractJson.Write(NpcWork.Create()));foreach(var p in NationalPersonnel.Catalog.People){Assert.Equal(old.Characters.Single(c=>c.Id==p.Id),fresh.Characters.Single(c=>c.Id==p.Id));Assert.Equal(old.Locations.Single(c=>c.Actor==p.Id),fresh.Locations.Single(c=>c.Actor==p.Id));}Assert.NotEqual(old.Definitions.Version,fresh.Definitions.Version);}
    [Fact] public void SealedOfferAndPhysicalReturnBelongToCreatedPerson(){var s=New();s.AdvanceTo(1);Assert.Empty(RegionalWork.Inbox(s));Assert.Equal(PersonalStart.Person,s.DiagnosticSnapshot().Tasks.Single().Executor);s.AdvanceTo(2);Assert.Null(RegionalWork.Inbox(s).Single().Task);Accept(s);s.AdvanceTo(9);var w=s.DiagnosticSnapshot();Assert.Equal(ExecutionPhase.Completed,w.Tasks.Single().Execution);Assert.True(NpcWork.Inputs(w,new("person:nobunaga"),s.Seconds).LastReportKnown);Assert.All(w.Requests,r=>Assert.Equal(PersonalStart.Person,r.Intent.Executor));}
    [Theory][InlineData(1)][InlineData(2)][InlineData(4)][InlineData(6)][InlineData(9)]
    public void JobSaveRestorationAndContinuationUseTheSamePerson(long at){var s=New();s.AdvanceTo(Math.Min(at,2));if(at>2){Accept(s);s.AdvanceTo(at);}var root=Path.Combine(Path.GetTempPath(),"hakutai-personal-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,PersonalStart.Create().Definitions);s.SetPaused(true);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetActorView(PersonalStart.Person)),ContractJson.Write(host.Current.GetActorView(PersonalStart.Person)));Continue(s);Continue(host.Current);var a=s.DiagnosticSnapshot();var b=host.Current.DiagnosticSnapshot();Assert.Equal(a.CommitSequence,b.CommitSequence);Assert.Equal(ContractJson.Write(a),ContractJson.Write(b));}
    [Theory][InlineData(1)][InlineData(1000)][InlineData(2000)]
    public void IndependentTravelIsRestoredWithoutMovingOldOfficer(long at){var s=New();var initial=s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==ContractFixture.Officer);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:personal-move","kofu"),s.Revision).Code);s.AdvanceTo(at);var copy=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.GetBranchView(PersonalStart.Person)),ContractJson.Write(copy.GetBranchView(PersonalStart.Person)));s.SetPaused(false);copy.SetPaused(false);long end=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[^1].EndAt;s.AdvanceTo(end);copy.AdvanceTo(end);Assert.Equal(ContractJson.Write(s.GetBranchView(PersonalStart.Person)),ContractJson.Write(copy.GetBranchView(PersonalStart.Person)));Assert.Equal(initial,s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==ContractFixture.Officer));Assert.Equal(new EntityId("person:shingen"),s.DiagnosticSnapshot().Tasks.Last().Issuer);}
    [Fact] public void PeaceStartCannotActivateArmiesOrClaimTax(){var s=New();Assert.Equal(ResultCode.NotAvailable,s.SetRegionalActive(true,s.Revision).Code);var w=s.DiagnosticSnapshot();w.Grants=[..w.Grants,w.Grants.First(g=>g.Actions.Contains(ActionKind.Transfer)) with{Id=new("grant:forged"),Agent=PersonalStart.Person}];Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void InvalidNamesFailBeforeAnyWorldIsCreated(){foreach(var name in new[]{"", " x", "x ","a\nb",new string('a',25)})Assert.Throws<InvalidDataException>(()=>PersonalStart.Create(name));}
    [Fact] public void DifferentDefinitionCannotRestorePersonalSlot(){var s=New();var root=Path.Combine(Path.GetTempPath(),"personal-deps-"+Guid.NewGuid().ToString("N"));new GenerationSaveStore(root,PersonalStart.Create().Definitions).Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,NpcWork.Create().Definitions).Prepare("case"));}
}
